{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_e7b4bc64f5118eeec7a5056c", "claim_ids": ["claim_396614eb5ee7eba368af3061", "claim_72c90a858b94e35577d3ac63"], "query_ids": ["q_365"], "claims": [{"claim_id": "claim_396614eb5ee7eba368af3061", "quote": "In November, the U.S. Department of Commerce issued a final decision on import duties on aluminum foil products from South Korea and Thailand.", "url": "https://www.packagingdive.com/news/aluminum-foil-flexible-packaging-duties/704216", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "antidumping and countervailing duty orders", "country_of_origin": "China", "exporting_country": "South Korea"}}, {"claim_id": "claim_72c90a858b94e35577d3ac63", "quote": "Commerce published such orders against China in 2018, and in 2022, it self-initiated countrywide circumvention inquiries to determine whether imports of aluminum foil completed in Korea and Thailand with Chinese", "url": "https://www.packagingdive.com/news/aluminum-foil-flexible-packaging-duties/704216", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"announcement_date": "2018"}}]}, {"pair_id": "conflict_4a62538a3569ec5907028c6b", "claim_ids": ["claim_c0435ea9111e26b921850abd", "claim_facc1ba0afa0e8ed607c78b9"], "query_ids": ["q_365"], "claims": [{"claim_id": "claim_c0435ea9111e26b921850abd", "quote": "According to trade groups, the very thin foil used in some flexible packaging is affected alongside other aluminum for which more robust domestic manufacturing exists, including that used in aluminum foil kitchen wrap or electric car batteries.", "url": "https://www.packagingdive.com/news/aluminum-foil-flexible-packaging-duties/704216", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "very thin foil used in some flexible packaging"}}, {"claim_id": "claim_facc1ba0afa0e8ed607c78b9", "quote": "All aluminum foil is covered by the orders regardless of specification. Excluded from the scope is “aluminum foil that is backed with paper, paperboard, plastics, or similar backing materials on one side or both sides of the aluminum foil, as well as etched capacitor foil and aluminum foil that is cut to shape.”", "url": "https://www.msci.org/united-states-will-investigate-aluminum-foil-from-imports-from-china-korea-and-thailand-2", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_8156a6e35f783f1850333062", "claim_ids": ["claim_0b042d4bad9b83f6d0bc2610", "claim_fe5ef641fa1846978cfcda0a"], "query_ids": ["q_366"], "claims": [{"claim_id": "claim_0b042d4bad9b83f6d0bc2610", "quote": "Starting August 1, 2025, President Trump imposed 50% tariffs on global imports of semi-finished copper products (e.g., copper pipes, wires, rods, sheets, and tubes) and copper-intensive derivative products", "url": "https://www.congress.gov/crs-product/IN12614", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"announcement_date": "August 1, 2025"}}, {"claim_id": "claim_fe5ef641fa1846978cfcda0a", "quote": "Effective April 6, 2026, President Trump imposed a _50% tariff on the full value_ of semi-finished copper products and _25% on the full value_ of copper-intensive derivative products (10% if at least 95% of the copper, steel, and aluminum in the product is U.S.-sourced)", "url": "https://www.congress.gov/crs-product/IN12614", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"effective_date": "April 6, 2026"}}]}, {"pair_id": "conflict_df0143a2b8004a009cec4023", "claim_ids": ["claim_29943c2f26936fecc1ff95de", "claim_74c22eeaf172d7c59264f8f8"], "query_ids": ["q_367"], "claims": [{"claim_id": "claim_29943c2f26936fecc1ff95de", "quote": "A 25% tariff on all steel and aluminium imports went into effect on March 12, under the umbrella of Section 232 of the 1962 Trade Expansion Act.", "url": "https://www.fastmarkets.com/insights/ghost-of-steel-past-a-timeline-of-2025-in-the-americas-steel-industry", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "legal_authority": "1962 Trade Expansion Act", "duty_rate": "25%", "effective_date": "March 12"}}, {"claim_id": "claim_74c22eeaf172d7c59264f8f8", "quote": "Georgia businesses that rely on steel and aluminum will face higher costs after import taxes on these metals were doubled to 50% on Wednesday.", "url": "https://www.wabe.org/steel-and-aluminum-tariffs-doubled-as-georgia-businesses-face-price-increases", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Georgia businesses", "tariff_program": "import taxes on these metals were doubled to 50%", "affected_product": "steel and aluminum"}}]}, {"pair_id": "conflict_ab31cbfdca3d9f698c6e2347", "claim_ids": ["claim_16460c9b68c493cd01e3aab8", "claim_82b99688be78d8ec5b8ddb32"], "query_ids": ["q_368"], "claims": [{"claim_id": "claim_16460c9b68c493cd01e3aab8", "quote": "The 10% tariff on aluminum imports has increased costs for extrusions by 8-12%, as domestic smelters cannot meet demand.", "url": "https://energy-solutions.co/supply-chain/risk-index/us-section-232-tariffs-steel-aluminum-wind-ev-costs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "10%"}}, {"claim_id": "claim_82b99688be78d8ec5b8ddb32", "quote": "Georgia businesses that rely on steel and aluminum will face higher costs after import taxes on these metals were doubled to 50% on Wednesday.", "url": "https://www.wabe.org/steel-and-aluminum-tariffs-doubled-as-georgia-businesses-face-price-increases", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Georgia businesses", "duty_rate": "50%", "effective_date": "Wednesday"}}]}, {"pair_id": "conflict_a11bbb1d1989d2a3221213c0", "claim_ids": ["claim_2bc877126d5a064640c57f78", "claim_b13ae1261d2ba99cba7b69a9"], "query_ids": ["q_368"], "claims": [{"claim_id": "claim_2bc877126d5a064640c57f78", "quote": "OEMs face a 25% cost premium on imported steel, but domestic steel is also priced higher due to reduced supply.", "url": "https://energy-solutions.co/supply-chain/risk-index/us-section-232-tariffs-steel-aluminum-wind-ev-costs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%"}}, {"claim_id": "claim_b13ae1261d2ba99cba7b69a9", "quote": "The Section 232 tariffs on steel (25%) and aluminum (10%) constitute a structural cost shock and supply-chain distortion for US wind and EV manufacturing.", "url": "https://energy-solutions.co/supply-chain/risk-index/us-section-232-tariffs-steel-aluminum-wind-ev-costs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "duty_rate": "25%"}}]}, {"pair_id": "conflict_c078ba59b3e5597f7b280277", "claim_ids": ["claim_5c3f3f333a94331788a2caf5", "claim_f9756ed67401e8bb1ae4e63d"], "query_ids": ["q_369"], "claims": [{"claim_id": "claim_5c3f3f333a94331788a2caf5", "quote": "German business leaders are expressing concerns that President Donald Trump’s 25 percent tariff on imported steel could affect the auto industry in the South.", "url": "https://aldailynews.com/fear-steel-tariff-hurt-auto-industry-south", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "German business leaders", "tariff_program": "25 percent tariff on imported steel", "duty_rate": "25 percent"}}, {"claim_id": "claim_f9756ed67401e8bb1ae4e63d", "quote": "Trump signed a proclamation last week to impose a 25 percent tariff on steel from every country except Canada and Mexico.", "url": "https://aldailynews.com/fear-steel-tariff-hurt-auto-industry-south", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25 percent tariff on steel", "duty_rate": "25 percent"}}]}, {"pair_id": "conflict_2e9c649e81f0748bb9c30bf5", "claim_ids": ["claim_6c837c5adf04f57adf9c52c5", "claim_70740bc6c0b79e15344938af"], "query_ids": ["q_369"], "claims": [{"claim_id": "claim_6c837c5adf04f57adf9c52c5", "quote": "On August 15, the US Department of Commerce expanded the list of goods subject to these 50% tariffs, adding 407 product categories of steel and aluminium derivative products", "url": "https://www.fastmarkets.com/insights/ghost-of-steel-past-a-timeline-of-2025-in-the-americas-steel-industry", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "50% tariffs", "effective_date": "August 15"}}, {"claim_id": "claim_70740bc6c0b79e15344938af", "quote": "A 25% tariff on all steel and aluminium imports went into effect on March 12, under the umbrella of Section 232 of the 1962 Trade Expansion Act. This new iteration barred previous country-specific exemptions and exclusions, including for the EU, Canada, Mexico, Japan and the UK.", "url": "https://www.fastmarkets.com/insights/ghost-of-steel-past-a-timeline-of-2025-in-the-americas-steel-industry", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 of the 1962 Trade Expansion Act", "duty_rate": "25%", "effective_date": "March 12"}}]}, {"pair_id": "conflict_52ad84769ce088167a2c3b0c", "claim_ids": ["claim_01fdfde67c437e49efa4afe2", "claim_dc6db724095c63bf7b73c7f5"], "query_ids": ["q_37"], "claims": [{"claim_id": "claim_01fdfde67c437e49efa4afe2", "quote": "The news came as President Donald Trump announced 25% tariffs on auto imports at the White House. Hyundai will be spared from those tariffs on its U.S.-made vehicles.", "url": "https://tedmag.com/hyundai-shows-off-new-7-6b-ev-plant-amid-tariff-announcement", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "tariff_program": "25% tariffs on auto imports", "legal_authority": "President Donald Trump", "duty_rate": "25%"}}, {"claim_id": "claim_dc6db724095c63bf7b73c7f5", "quote": "This plant couldn’t come at a better time than now,” Munoz told reporters, “because definitely all the cars that we would produce here are going to be exempted from any tariffs.”", "url": "https://tedmag.com/hyundai-shows-off-new-7-6b-ev-plant-amid-tariff-announcement", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "exempted from any tariffs"}}]}, {"pair_id": "conflict_d90565a09ed625a5be224399", "claim_ids": ["claim_102f27c721dcc1b883db3ac6", "claim_2640566dc8a526e3a8ecae6f"], "query_ids": ["q_371"], "claims": [{"claim_id": "claim_102f27c721dcc1b883db3ac6", "quote": "President Donald Trump’s tariffs on imported steel and aluminum have officially gone into effect.", "url": "https://glc-inc.com/2025/03/steel-tariffs-a-new-challenge-for-the-automotive-industry", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "tariffs on imported steel and aluminum", "reported_policy_status": "officially gone into effect"}}, {"claim_id": "claim_2640566dc8a526e3a8ecae6f", "quote": "President Donald Trump signed executive orders placing 25% tariffs on all steel and aluminum imports into the U.S. on Monday.", "url": "https://www.wardsauto.com/news/archive-auto-tariffs-trump-steel-aluminum-automotive/739872", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariffs on all steel and aluminum imports", "legal_authority": "executive orders", "duty_rate": "25%", "announcement_date": "Monday"}}]}]}

